test('Biodome destruction and partial structural damage kill corresponding residents without repeat damage',()=>{const g=game();g.run('const killer=Object.keys(SHIPS).find(id=>SHIPS[id].type==="Struc");SHIPS[killer].damage=500;SHIPS[killer].guns=1;window.testKiller=killer');assert.equal(g.run('resolveBiodomeDamage({[testKiller]:1},1,0,1050).populationLost'),25);assert.equal(g.run('resolveBiodomeDamage({[testKiller]:1},1,0,1050).damageAfter'),500);assert.equal(g.run('resolveBiodomeDamage({[testKiller]:1},1,500,1025).populationLost'),25);assert.equal(g.run('resolveBiodomeDamage({[testKiller]:1},1,500,1025).destroyed'),1);assert.equal(g.run('resolveBiodomeDamage({},1,500,1025).populationLost'),0);assert.equal(g.run('resolveBiodomeDamage({[testKiller]:100},2,0,30).populationLost'),0);g.run('state.buildings.biodome=1;state.biodomeDamage=500');assert.equal(g.run('populationCapacity()'),1025);});
