function game(saved,initialRender=false){
  const elements=new Map(),listeners={};const element=()=>({innerHTML:'',textContent:'',value:'',checked:false,dataset:{},style:{setProperty(){}},classList:{add(){},remove(){},toggle(){}},addEventListener(){},append(){},remove(){},setAttribute(){}});
  const document={getElementById(id){if(!elements.has(id))elements.set(id,element());return elements.get(id);},querySelector(){return null;},querySelectorAll(){return [];},createElement:element,body:element(),addEventListener(type,fn){(listeners[type]||=[]).push(fn);}};
  const store={};if(saved)store['starfall-round-v2']=JSON.stringify(saved);
  const context=vm.createContext({console,document,localStorage:{getItem:k=>store[k]||null,setItem:(k,v)=>store[k]=v},setTimeout(){},setInterval(){},confirm:()=>true,location:{hash:'',reload(){}},navigator:{}});context.window=context;
  vm.runInContext(fs.readFileSync(path.join(__dirname,'../dist/ship-catalog.js'),'utf8'),context);vm.runInContext(fs.readFileSync(path.join(__dirname,'../dist/fleet-features.js'),'utf8'),context);vm.runInContext(fs.readFileSync(path.join(__dirname,'../dist/admin-alliances.js'),'utf8'),context);
  const source=fs.readFileSync(path.join(__dirname,'../dist/game.js'),'utf8').replace('normalizeGalaxySlots();update();setInterval(updateCountdown,1000);',initialRender?'normalizeGalaxySlots();update();setInterval(updateCountdown,1000);':'normalizeGalaxySlots();');vm.runInContext("var originalTestRandom=Math.random;Math.random=()=>0;",context);vm.runInContext(source,context);vm.runInContext("Math.random=originalTestRandom;",context);
  return {context,document,elements,store,run:code=>vm.runInContext(code,context)};
}
test('migrates all existing planets into 1–10 without data loss',()=>{const g=game();assert.equal(g.run('state.galaxy.length'),15);assert.ok(g.run('state.galaxy.every(p=>Number(p.coords.split(":")[2])<=10)'));assert.equal(g.run('new Set(state.galaxy.map(p=>p.coords)).size'),15);assert.equal(g.run('state.alliance.members.find(m=>m.name==="Sera Dain").coords'),g.run('state.galaxy.find(p=>p.ruler==="Sera Dain").coords'));const before=g.run('JSON.stringify(state.galaxy)');g.run('normalizeGalaxySlots()');assert.equal(g.run('JSON.stringify(state.galaxy)'),before);});
test('all local, simulated and empty galaxies always render 15 slots',()=>{const g=game();for(const coords of ['{x:7,y:4}','{x:7,y:5}','{x:8,y:6}']){g.run(`state.browserCoords=${coords};renderGalaxyBrowser()`);assert.equal((g.elements.get('browserPlanetRows').innerHTML.match(/<tr/g)||[]).length,15);assert.equal((g.elements.get('browserPlanetMap').innerHTML.match(/class="planet-chip/g)||[]).length,15);assert.equal((g.elements.get('browserPlanetRows').innerHTML.match(/Empty \/ Reserved/g)||[]).length,5);}});
