test('self exile is unchecked, cancellable, moves to a different galaxy and preserves assets',()=>{const g=game();g.run('renderPlanetSettings()');assert.match(g.elements.get('planetSettingsContent').innerHTML,/EXILE OPTION/);assert.doesNotMatch(g.elements.get('planetSettingsContent').innerHTML,/id="selfExile"[^>]*checked/);g.run('state.resources={metal:100000,crystal:100000,eonium:100000}');const before=g.run('JSON.stringify(state)');const checkbox={checked:true};g.context.confirm=()=>false;g.run('requestSelfExile') (checkbox);assert.equal(checkbox.checked,false);assert.equal(g.run('JSON.stringify(state)'),before);g.context.confirm=()=>true;g.run('update=()=>save()');const cost=g.run('selfExileCost()');const resources=g.run('state.resources.metal');const assets=g.run('JSON.stringify([state.fleets,state.buildings,state.research,state.roids,state.population,state.missions])');checkbox.checked=true;g.run('requestSelfExile')(checkbox);assert.notEqual(g.run('homeGalaxy()'),'07:04');assert.equal(g.run('state.resources.metal'),resources-cost);assert.equal(g.run('state.selfExileCount'),1);assert.equal(g.run('state.galaxyFunds["07:04"].metal'),cost);assert.equal(g.run('JSON.stringify([state.fleets,state.buildings,state.research,state.roids,state.population,state.missions])'),assets);assert.equal(g.run('state.alliance.members.find(m=>m.name==="A. Commander").coords'),g.run('state.galaxy.find(p=>p.player).coords'));const saved=JSON.parse(g.store['starfall-round-v2']);assert.equal(game(saved).run('homeGalaxy()'),g.run('homeGalaxy()'));});
test('stronghold passive bonus and daily reward exclude remote and non-alliance planets',()=>{const g=game();g.run('state.alliance.fortress.strongholdGalaxy="07:04"');assert.equal(g.run('allianceIncomeMultiplier("A. Commander")'),1.0025);assert.equal(g.run('allianceIncomeMultiplier("Sera Dain")'),1);assert.equal(g.run('allianceIncomeMultiplier("Unknown")'),1);g.run('state.alliance.fortress.lastDistorterTick=1;state.tick=25;grantDailyDistorters()');assert.equal(g.run('state.buildings.waveDistorter'),1);assert.equal(g.run('state.galaxy.find(p=>p.ruler==="Nira Sol").waveDistorters'),1);assert.equal(g.run('state.galaxy.find(p=>p.ruler==="Sera Dain").waveDistorters||0'),0);g.run('grantDailyDistorters()');assert.equal(g.run('state.buildings.waveDistorter'),1);assert.match(g.run('allianceFortressHTML()'),/MEMBERS IN STRONGHOLD GALAXY/);g.run('movePlanet(state.galaxy.find(p=>p.player),"07:06:01")');assert.equal(g.run('allianceIncomeMultiplier("A. Commander")'),1);});
test('custom and paste coordinates validate, persist and remain beneath scan coordinates',()=>{const g=game();assert.equal(g.run('JSON.stringify(parseCustomScanCoordinates("2:7"))'),'{"x":"07","y":"02","z":"07"}');assert.equal(g.run('JSON.stringify(parseCustomScanCoordinates("08:06:15"))'),'{"x":"08","y":"06","z":"15"}');for(const text of ['2:16','0:1','<script>','2:7\n3:8'])assert.equal(g.run(`parseCustomScanCoordinates(${JSON.stringify(text)})`),null);g.run('renderWaves()');const html=g.elements.get('wavesContent').innerHTML;assert.ok(html.indexOf('customScanCoordinates')>html.indexOf('SCAN COORDINATES'));assert.match(html,/pasteScanCoordinates/);g.document.getElementById('pasteScanCoordinates').value='2:7';g.run('applyCustomScanCoordinates("paste")');assert.equal(g.run('state.waves.targetCoords.z'),'07');assert.match(g.elements.get('scanCoordinateFeedback').textContent,/07:02:07/);});
