test('full rendering, hourly tick, economy, construction and research remain functional',()=>{const g=game();g.run('state.buildings.lightFactory=1;state.buildings.mediumFactory=1;state.research.fighter=1;state.research.corvette=1;state.research.frigate=1');g.run('update()');assert.match(g.elements.get('wavesContent').innerHTML,/AVAILABLE SCANS/);assert.match(g.elements.get('shipCards').innerHTML,/ORDER NOW/);const before=g.run('state.resources.metal');g.run('tickOnce()');assert.equal(g.run('state.tick'),2);assert.ok(g.run('state.resources.metal')>before);assert.ok(g.run('Object.keys(SHIPS).length')>=36);});

test('manual self exile cost, free doubling, increasing costs and payment guards',()=>{const g=game();assert.equal(g.run('calculateSelfExileCost(10000,0,100,100)'),5000);assert.equal(g.run('calculateSelfExileCost(10000,0,100,100,true)'),10000);assert.equal(g.run('calculateSelfExileCost(10000,1,100,100)'),23627);g.run('renderPlanetSettings()');assert.match(g.elements.get('planetSettingsContent').innerHTML,/Planetarion cost formula/);g.run('update=()=>save();state.resources={metal:0,crystal:0,eonium:0}');const before=g.run('JSON.stringify(state)');g.run('requestSelfExile')({checked:true});assert.equal(g.run('JSON.stringify(state)'),before);g.run('state.resources={metal:100000,crystal:100000,eonium:100000};state.missions=[{id:"away",ships:{}}]');const coords=g.run('homeGalaxy()');g.run('requestSelfExile')({checked:true});assert.equal(g.run('homeGalaxy()'),coords);});

test('Administration submenu items open each existing subpage directly',()=>{const g=game();g.run('window.isGameAdmin=true;window.useLegacyStaffView=true;window.scrollTo=()=>{}');for(const [page,label] of [['adminRound','ROUND CONFIGURATION'],['adminPlanets','PLANET EDITOR'],['adminShips','SHIP STAT CONFIGURATION'],['adminState','ADVANCED ROUND STATE']]){g.run('navigate('+JSON.stringify(page)+')');const content=g.elements.get('adminContent').innerHTML;assert.match(content,new RegExp(label));assert.doesNotMatch(content,/admin-subnav/);}});
test('planet editor coordinate selectors reject occupied and reserved slots',()=>{const g=game();g.run('window.isGameAdmin=true;window.useLegacyStaffView=true;window.scrollTo=()=>{};openPlanetEditor("ally1")');assert.equal(g.run('state.adminSelected'),'ally1');assert.match(g.elements.get('adminContent').innerHTML,/Planet location · all galaxies/);for(const [id,value] of [['admCoordX','7'],['admCoordY','4'],['admCoordZ','11']])g.document.getElementById(id).value=value;assert.equal(g.run('chosenAdminCoordinates()'),null);g.document.getElementById('admCoordZ').value='1';const before=g.run('JSON.stringify(state)');g.run('saveAdminPlanet()');assert.equal(g.run('JSON.stringify(state)'),before);g.document.getElementById('admCoordX').value='100';g.document.getElementById('admCoordY').value='100';g.document.getElementById('admCoordZ').value='10';assert.equal(g.run('chosenAdminCoordinates()'),'100:100:10');g.run('renderGalaxyBrowser()');assert.match(g.elements.get('browserPlanetRows').innerHTML,/data-edit-planet="ally1"/);});
test('creating an alliance preserves existing planets and adds five unassigned dummy planets',()=>{const g=game();g.run('window.isGameAdmin=true;window.useLegacyStaffView=true;window.scrollTo=()=>{}');g.document.getElementById('newAllianceName').value='Test Alliance';g.document.getElementById('newAllianceTag').value='TEST';const count=g.run('state.galaxy.length');g.run('createAlliance()');assert.equal(g.run('state.alliance.name'),'Test Alliance');assert.equal(g.run('state.alliance.members[0].rank'),'Owner');assert.equal(g.run('state.galaxy.length'),count+5);assert.equal(g.run('state.galaxy.filter(p=>p.dummy&&p.alliance==="Unaffiliated").length'),5);g.run('const dummy=state.galaxy.find(p=>p.dummy);dummy.alliance=state.alliance.name;syncEditedAllianceMember(dummy)');assert.equal(g.run('state.alliance.members.length'),2);assert.equal(g.run('state.alliance.members[1].rank'),'Member');const before=g.run('state.galaxy.length');g.run('createAlliance()');assert.equal(g.run('state.galaxy.length'),before);});
test('admin dummy button assigns a unique planet and persists membership without replacing existing members',()=>{const g=game();g.run('update=()=>save()');g.document.getElementById('admDummyAlliance').value='Vesper Pact';const count=g.run('state.galaxy.length'),members=g.run('state.alliance.members.length');g.run('addAdminDummyMember()');assert.equal(g.run('state.galaxy.length'),count+1);assert.equal(g.run('state.alliance.members.length'),members+1);assert.equal(g.run('state.galaxy.at(-1).alliance'),'Vesper Pact');assert.ok(g.run('state.galaxy.at(-1).dummy'));assert.equal(g.run('new Set(state.galaxy.map(p=>p.coords)).size'),count+1);assert.equal(game(JSON.parse(g.store['starfall-round-v2'])).run('state.alliance.members.length'),members+1);g.document.getElementById('admDummyAlliance').value='Invalid';g.run('addAdminDummyMember()');assert.equal(g.run('state.galaxy.length'),count+1);g.run('while(state.galaxy.length<40)state.galaxy.push({...state.galaxy.at(-1),id:"limit"+state.galaxy.length})');g.document.getElementById('admDummyAlliance').value='Vesper Pact';g.run('addAdminDummyMember()');assert.equal(g.run('state.galaxy.length'),40);});
test('admin galaxy browser has 15 slots, editor links and wrapping navigation',()=>{const g=game();assert.equal((g.run('adminGalaxyBrowserHTML()').match(/<tr(?: [^>]*)?>/g)||[]).length,16);assert.match(g.run('adminGalaxyBrowserHTML()'),/data-edit-planet="home"/);g.document.getElementById('admBrowserX').value='100';g.document.getElementById('admBrowserY').value='100';g.run('browseAdminGalaxy(1)');assert.equal(g.run('JSON.stringify(state.adminBrowserCoords)'),'{"x":1,"y":1}');g.run('state.adminBrowserCoords={x:100,y:100}');assert.equal((g.run('adminGalaxyBrowserHTML()').match(/Empty \/ Reserved/g)||[]).length,5);});
test('planet tools unlock all research and add exactly one of every construction',()=>{const g=game();g.run('update=()=>save()');const before=JSON.parse(g.run('JSON.stringify(state.buildings)'));g.run('applyPlanetTools("research")');assert.ok(g.run('TECH_TREE.every(t=>state.research[t.id]===t.max)'));g.run('applyPlanetTools("construction")');for(const id of g.run('Object.keys(BUILDINGS)'))assert.equal(g.run(`state.buildings[${JSON.stringify(id)}]`),(before[id]||0)+1);});
test('Havoc applies global numbers instantly and reset restores the prior configuration after reload',()=>{const g=game();g.run('adminTab="havoc";update=()=>save();state.galaxy[1].race="Cathaar"');const before=g.run('JSON.stringify([state.resources,state.roids,state.fleets,state.research,state.buildings,state.config.tickHours,state.galaxy])');const html=g.run('adminHavocHTML()');assert.doesNotMatch(html,/id="havocPlanet"|LOAD CONFIGURATION/);assert.match(html,/RESET TO PREVIOUS/);for(const id of g.run('Object.keys(RES)')){g.document.getElementById('havocResource-'+id).value='12345';g.document.getElementById('havocRoids-'+id).value='42';}for(const t of g.run('TECH_TREE'))g.document.getElementById('admTech-'+t.id).value=t.max;for(const id of g.run('Object.keys(BUILDINGS)'))g.document.getElementById('admBuild-'+id).value='3';for(const cls of g.run('HAVOC_CLASSES'))g.document.getElementById('havocClass-'+cls).value='17';g.document.getElementById('havocTickMinutes').value='5';g.run('applyPlanetTools("all")');assert.ok(g.run('state.galaxy.every(p=>p.resources.metal===12345&&p.roids.metal===42)'));assert.equal(g.run('state.config.tickHours'),5/60);assert.ok(g.run('TECH_TREE.every(t=>state.research[t.id]===t.max)'));assert.ok(g.run('Object.values(state.buildings).every(n=>n===3)'));for(const cls of g.run('HAVOC_CLASSES')){const sum=g.run(`Object.entries(SHIPS).filter(([id,d])=>d.race===state.race&&d.class===${JSON.stringify(cls)}).reduce((n,[id])=>n+state.fleets.base[id],0)`);const exists=g.run(`Object.values(SHIPS).some(d=>d.race===state.race&&d.class===${JSON.stringify(cls)})`);assert.equal(sum,exists?17:0);}const restored=game(JSON.parse(g.store['starfall-round-v2']));restored.run('update=()=>save();resetHavoc()');assert.equal(restored.run('JSON.stringify([state.resources,state.roids,state.fleets,state.research,state.buildings,state.config.tickHours,state.galaxy])'),before);});
test('admin assigns an existing dummy and its member appears immediately',()=>{const g=game();g.run('window.isGameAdmin=true;window.useLegacyStaffView=true;window.isGameAdmin=true;window.useLegacyStaffView=true;window.scrollTo=()=>{}');g.document.getElementById('newAllianceName').value='Dummy Test';g.document.getElementById('newAllianceTag').value='DTEST';g.run('createAlliance()');const id=g.run('state.galaxy.find(p=>p.dummy).id');g.document.getElementById('allianceDummyPlanet').value=id;g.run('assignAllianceDummy()');assert.equal(g.run('state.alliance.members.length'),2);assert.match(g.run('allianceMembersHTML()'),/Practice Commander 1/);});
test('members exchange fund resources at five percent loss while preserving every reserve minimum',()=>{const g=game();g.run('update=()=>save();state.alliance.members.find(m=>m.name==="A. Commander").rank="Member";state.alliance.fund={metal:2000,crystal:1000,eonium:1000};state.alliance.fundMinimum={metal:1000,crystal:1000,eonium:1000}');assert.equal(g.run('mayAlliance("exchange")'),true);assert.equal(g.run('mayAlliance("fundMinimum")'),false);assert.match(g.run('allianceFundHTML()'),/MINIMUM FUND RESERVES/);for(const [id,value] of [['fundExchangePool','fund'],['fundExchangeFrom','metal'],['fundExchangeTo','crystal'],['fundExchangeAmount','1001']])g.document.getElementById(id).value=value;let before=g.run('JSON.stringify(state)');g.run('exchangeAllianceResources()');assert.equal(g.run('JSON.stringify(state)'),before);g.document.getElementById('fundExchangeAmount').value='1000';g.run('exchangeAllianceResources()');assert.equal(g.run('state.alliance.fund.metal'),1000);assert.equal(g.run('state.alliance.fund.crystal'),1950);before=g.run('JSON.stringify(state)');g.run('saveAllianceFundMinimum()');assert.equal(g.run('JSON.stringify(state)'),before);g.document.getElementById('fundExchangeFrom').value='invalid';g.run('exchangeAllianceResources()');assert.equal(g.run('JSON.stringify(state)'),before);});
test('rank permissions can grant and revoke HC actions for every rank and persist',()=>{const g=game();g.run('update=()=>save();state.alliance.members.find(m=>m.name==="A. Commander").rank="Officer"');assert.equal(g.run('mayAlliance("war")'),false);g.run('state.alliance.rankPermissions=defaultAlliancePermissions();state.alliance.rankPermissions.Officer.war=true');assert.equal(g.run('mayAlliance("war")'),true);g.run('declareAllianceDiplomacy=(target,action)=>{state.alliance.wars.push(target)};allianceAction("toggleWar",{dataset:{war:"Test Enemy"}})');assert.ok(g.run('state.alliance.wars.includes("Test Enemy")'));g.run('state.alliance.rankPermissions.Officer.war=false');const before=g.run('JSON.stringify(state)');g.run('allianceAction("toggleWar",{dataset:{war:"Test Enemy"}})');assert.equal(g.run('JSON.stringify(state)'),before);g.run('save()');assert.equal(game(JSON.parse(g.store['starfall-round-v2'])).run('mayAlliance("war")'),false);assert.match(g.run('allianceRanksHTML()'),/Recruit/);});
test('donations are charged once, delayed eight ticks, and enforce cumulative limits',()=>{const g=game();g.run('update=()=>save();state.resources.metal=100000');g.document.getElementById('fundResource').value='metal';const cap=g.run('Math.floor(income().metal*2)');g.document.getElementById('fundAmount').value=String(cap);const fund=g.run('state.alliance.fund.metal');g.run('donateAllianceFund()');assert.equal(g.run('state.resources.metal'),100000-cap);assert.equal(g.run('state.alliance.fund.metal'),fund);assert.equal(g.run('state.alliance.pendingDonations.at(-1).tick'),g.run('state.tick')+8);const before=g.run('JSON.stringify(state)');g.document.getElementById('fundAmount').value='1';g.run('donateAllianceFund()');assert.equal(g.run('JSON.stringify(state)'),before);g.document.getElementById('fundAmount').value='0.5';g.run('donateAllianceFund()');assert.equal(g.run('JSON.stringify(state)'),before);});
test('alliance intel browser has fifteen slots and independent coordinates',()=>{const g=game();g.run('allianceTab="intel"');const before=g.run('JSON.stringify(state.browserCoords)');assert.equal((g.run('allianceIntelHTML()').match(/<tr(?: [^>]*)?>/g)||[]).length,16);g.document.getElementById('intelSector').value='100';g.document.getElementById('intelGalaxy').value='100';g.run('browseAllianceIntel(1)');assert.equal(g.run('JSON.stringify(state.alliance.intelBrowserCoords)'),'{"x":1,"y":1}');assert.equal(g.run('JSON.stringify(state.browserCoords)'),before);assert.equal(g.run('browserGalaxyData({x:8,y:9}).planets.length'),0);assert.equal(g.run('JSON.stringify(state.browserCoords)'),before);});
test('intel notes persist and rank permissions prevent unauthorized editing',()=>{const g=game();g.run('state.alliance.intelTarget="07:04:02"');g.document.getElementById('intelThreat').value='Hostile';g.document.getElementById('intelNote').value='Fleet moving at dawn';g.run('saveAllianceIntel()');assert.equal(g.run('state.alliance.intelRecords["07:04:02"].status'),'Hostile');assert.equal(game(JSON.parse(g.store['starfall-round-v2'])).run('state.alliance.intelRecords["07:04:02"].note'),'Fleet moving at dawn');g.run('state.alliance.members.find(m=>m.name==="A. Commander").rank="Member"');assert.equal(g.run('mayAlliance("intel")'),true);assert.equal(g.run('mayAlliance("intelNotes")'),false);const before=g.run('JSON.stringify(state)');g.document.getElementById('intelNote').value='Unauthorized change';g.run('saveAllianceIntel()');assert.equal(g.run('JSON.stringify(state)'),before);assert.doesNotMatch(g.run('intelReportHTML([{type:"unit",name:"Unit",tick:2,text:"<script>"}])'),/data-scan=|<script>/);});
test('creating an alliance replaces the creation form with statistics and persists',()=>{const g=game();g.run('window.isGameAdmin=true;window.useLegacyStaffView=true;window.scrollTo=()=>{};state.alliance.name="Unaffiliated";state.alliance.members=[];renderCreatedAllianceStats()');assert.equal(g.document.getElementById('allianceCreatePanel').hidden,false);g.document.getElementById('newAllianceName').value='Stats Alliance';g.document.getElementById('newAllianceTag').value='STATS';g.run('createAlliance()');assert.equal(g.document.getElementById('allianceCreatePanel').hidden,true);assert.equal(g.document.getElementById('allianceStatistics').hidden,false);assert.match(g.document.getElementById('allianceStatistics').innerHTML,/Stats Alliance|FUND RESOURCES/);const restored=game(JSON.parse(g.store['starfall-round-v2']));restored.run('renderCreatedAllianceStats()');assert.equal(restored.document.getElementById('allianceCreatePanel').hidden,true);});
test('ordinary and alliance intel browsers share planet and structure data',()=>{const g=game();g.run('state.browserCoords={x:7,y:4};state.alliance.intelBrowserCoords={x:7,y:4};state.galaxy.find(p=>p.id==="ally1").name="Shared Planet Update";state.structurePlanets.push({id:"shared-structure",name:"Shared Stronghold",coords:"07:04:11",slot:11,alliance:state.alliance.name});renderGalaxyBrowser()');assert.match(g.document.getElementById('browserPlanetRows').innerHTML,/Shared Planet Update/);assert.match(g.run('allianceIntelHTML()'),/Shared Planet Update/);assert.match(g.document.getElementById('browserPlanetRows').innerHTML,/Shared Stronghold/);assert.match(g.run('allianceIntelHTML()'),/Shared Stronghold/);});

test('intel dropdowns include every alliance and relations color rows with latest scan links',()=>{const g=game();g.run('state.alliance.intelRecords={"07:04:02":{relation:"NAP",targetAlliance:"Ashen Banner"}};state.waves.scans=[{id:"p",coords:"07:04:02",type:"planet",name:"Planet scan",tick:5},{id:"old",coords:"07:04:02",type:"planet",tick:1}];');const html=g.run('allianceIntelHTML()');assert.match(html,/data-intel-affiliation="07:04:02"/);assert.match(html,/intel-relation-nap/);assert.match(html,/Latest scans/);assert.equal((html.match(/data-intel-scan-coords="07:04:02"/g)||[]).length,1);assert.match(html,/T5/);assert.match(html,/Ashen Banner/);g.run('state.alliance.rankPermissions={HC:{intelNotes:false}}');assert.match(g.run('allianceIntelHTML()'),/data-intel-affiliation="07:04:02" disabled/);});

test('fleet launch selectors start outbound missions and recall returns exactly those ships',()=>{for(const fid of ['f1','f2','f3']){const g=game();g.run('update=()=>save()');g.run('state.fleets['+JSON.stringify(fid)+'][Object.keys(SHIPS)[0]]=5');g.document.getElementById('missionFleet').value=fid;g.document.getElementById('missionTarget').value=g.run('state.galaxy.find(p=>!p.player).id');g.document.getElementById('missionType').value='Defence';const before=g.run('JSON.stringify(state.fleets['+JSON.stringify(fid)+'])');const count=g.run('totalShips(state.fleets['+JSON.stringify(fid)+'])');g.run('launchMission()');assert.equal(g.run('state.missions.length'),1);assert.equal(g.run('state.missions[0].fleet'),fid);assert.equal(g.run('state.missions[0].phase'),'outbound');assert.equal(g.run('totalShips(state.fleets['+JSON.stringify(fid)+'])'),0);assert.equal(g.run('totalShips(state.missions[0].ships)'),count);g.run('recallMission(state.missions[0].id);tickOnce()');assert.equal(g.run('state.missions.length'),0);assert.equal(g.run('JSON.stringify(state.fleets['+JSON.stringify(fid)+'])'),before);}const html=fs.readFileSync(path.join(__dirname,'../dist/index.html'),'utf8');for(const n of [1,2,3])assert.match(html,new RegExp('value="f'+n+'">Fleet '+n));});
test('launch protection and empty fleet guards preserve ships without creating orders',()=>{const g=game();g.run('update=()=>save()');g.document.getElementById('missionFleet').value='f1';g.document.getElementById('missionTarget').value=g.run('state.galaxy.find(p=>!p.player).id');g.document.getElementById('missionType').value='Attack';const before=g.run('JSON.stringify(state.fleets)');g.run('launchMission()');assert.equal(g.run('state.missions.length'),0);assert.equal(g.run('JSON.stringify(state.fleets)'),before);g.run('state.tick=30;state.fleets.f1=normalizeFleet({})');g.run('launchMission()');assert.equal(g.run('state.missions.length'),0);});

test('galaxy all scans preserves every report and charges the aggregate bill once',()=>{const g=game();g.run('update=()=>save();state.userSettings.allianceScansEnabled=true;state.buildings.waveAmplifier=1;state.research.scans=7;state.waves.galaxyScanType="all";state.resources={metal:1000000,crystal:1000000,eonium:1000000};state.waves.fundSources["A. Commander"]="personal"');const targets=g.run('state.galaxy.filter(p=>!p.player&&!p.exiled&&galaxyOf(p.coords)===homeGalaxy()).length'),bill=g.run('SCAN_TYPES.reduce((n,t)=>n+scanCost(t[2]),0)')*targets;g.run('runGalaxyScan()');assert.equal(g.run('state.waves.scans.length'),targets*8);assert.equal(g.run('new Set(state.waves.scans.map(s=>s.type)).size'),8);assert.equal(g.run('state.resources.metal'),1000000-bill);g.run('renderWaves()');assert.match(g.elements.get('wavesContent').innerHTML,/type="radio" name="galaxyScanType" value="all" checked/);assert.doesNotMatch(g.elements.get('wavesContent').innerHTML,/<select id="galaxyScanType"/);});
test('all scans skips locked types and insufficient funds leave the sweep untouched',()=>{const g=game();g.run('update=()=>save();state.userSettings.allianceScansEnabled=true;state.buildings.waveAmplifier=1;state.research.scans=1;state.waves.galaxyScanType="all";state.resources={metal:1000000,crystal:1000000,eonium:1000000};state.waves.fundSources["A. Commander"]="personal";runGalaxyScan()');assert.equal(g.run('new Set(state.waves.scans.map(s=>s.type)).size'),2);const before=g.run('state.waves.scans.length');g.run('state.resources={metal:0,crystal:0,eonium:0};runGalaxyScan()');assert.equal(g.run('state.waves.scans.length'),before);});

