test('Apply to order number updates only active throughput and preserves paid progress',()=>{const g=game();g.run('update=()=>save();state.production={id:Object.keys(SHIPS)[0],qty:10,total:50000,remaining:30000,cost:{metal:100}};state.productionQueue=[{id:Object.keys(SHIPS)[0],qty:5,total:10000,remaining:10000,cost:{metal:50}}];normalizeFactoryAssignments()');const initial=g.run('productionRate()'),queue=g.run('JSON.stringify(state.productionQueue)'),money=g.run('JSON.stringify(state.resources)');g.run('state.buildings.lightFactory=20;state.factoryAssignments.lightFactory=20');assert.equal(g.run('productionRate()'),initial);g.run('applyFactoriesToOrder(state.production.orderNumber)');assert.ok(g.run('productionRate()')>initial);assert.equal(g.run('state.production.remaining'),30000);assert.equal(g.run('JSON.stringify(state.productionQueue)'),queue);assert.equal(g.run('JSON.stringify(state.resources)'),money);const rate=g.run('productionRate()');g.run('tickOnce()');assert.equal(g.run('state.production.remaining'),30000-rate);assert.match(g.run('productionFactoryHTML()'),/APPLY TO ORDER #/);});

test('admin assignments synchronize non-current alliances and retain rank across renamed planets',()=>{const g=game();g.run('update=()=>save();var p=state.galaxy.find(p=>!p.player);var before=copy(p);p.alliance="Other Alliance";syncEditedAllianceMember(p,before);reconcileAllianceMembers()');assert.equal(g.run('allianceProfile("Other Alliance").members.filter(m=>m.planetId===p.id).length'),1);assert.equal(g.run('state.alliance.members.filter(m=>m.planetId===p.id||m.planet===p.name).length'),0);g.run('allianceProfile("Other Alliance").members[0].rank="Officer";before=copy(p);p.name="Renamed Planet";p.ruler="Renamed Commander";syncEditedAllianceMember(p,before)');assert.equal(g.run('allianceProfile("Other Alliance").members[0].rank'),'Officer');assert.equal(g.run('allianceProfile("Other Alliance").members[0].planet'),'Renamed Planet');g.run('state.alliance.members=[];p.alliance=state.alliance.name;reconcileAllianceMembers()');assert.ok(g.run('state.alliance.members.some(m=>m.planetId===p.id)'));});

test('planet editor has separate modules and applying resources leaves other edits untouched',()=>{const g=game();g.context.isGameAdmin=true;g.run('state.adminSelected="ally1";adminTab="planets";renderAdmin()');const html=g.elements.get('adminContent').innerHTML;assert.equal((html.match(/data-apply-planet-module=/g)||[]).length,8);assert.doesNotMatch(html,/SAVE PLANET/);g.document.getElementById('admName').value='Unsaved name';for(const r of ['metal','crystal','eonium'])g.document.getElementById('admRes-'+r).value='100';const before=g.run('JSON.stringify([state.galaxy[1].name,state.galaxy[1].alliance,state.galaxy[1].coords,state.galaxy[1].roids,state.galaxy[1].ships])');g.run('applyAdminPlanetModule("resources")');assert.equal(g.run('JSON.stringify(state.galaxy[1].resources)'),'{"metal":100,"crystal":100,"eonium":100}');assert.equal(g.run('JSON.stringify([state.galaxy[1].name,state.galaxy[1].alliance,state.galaxy[1].coords,state.galaxy[1].roids,state.galaxy[1].ships])'),before);});
test('module validation is atomic and location applies without reading identity or economy inputs',()=>{const g=game();g.context.isGameAdmin=true;g.run('update=()=>save();state.adminSelected="ally1"');const before=g.run('JSON.stringify(state.galaxy[1])');g.document.getElementById('admRes-metal').value='300';g.document.getElementById('admRes-crystal').value='-1';g.document.getElementById('admRes-eonium').value='300';g.run('applyAdminPlanetModule("resources")');assert.equal(g.run('JSON.stringify(state.galaxy[1])'),before);for(const [id,n] of [['admCoordX','8'],['admCoordY','3'],['admCoordZ','2']])g.document.getElementById(id).value=n;g.run('applyAdminPlanetModule("location")');assert.equal(g.run('state.galaxy[1].coords'),'08:03:02');assert.equal(g.run('state.alliance.members.find(m=>m.planetId===state.galaxy[1].id).coords'),'08:03:02');});

test('shared round reset restores race and canonical fleet ids for editor modules',()=>{const g=game();g.run(fs.readFileSync(path.join(__dirname,'../dist/planets.js'),'utf8').replace('initializePlanetDirectory();setInterval(refreshSharedPlanets,15000);',''));g.run('var defaults=freshState();var data={userId:"admin",revision:1,resetGeneration:1,canEdit:true,planets:defaults.galaxy,structures:[],alliances:[defaults.alliance]};applySharedDirectory(data)');assert.equal(g.run('state.race'),'Terran');assert.ok(g.run('Object.keys(state.fleets.base).every(id=>SHIPS[id])'));assert.match(g.run('adminPlanetEditorHTML(state.galaxy.find(p=>p.player))'),/admShip-terran-/);});

test('round state includes a separate reset panel and explicit confirmation stage',()=>{const g=game();g.run('window.isGameAdmin=true;adminTab="state";renderAdmin()');const html=g.elements.get('adminContent').innerHTML;assert.match(html,/round-state-reset/);assert.match(html,/data-open-round-reset>RESET ROUND/);assert.match(html,/Accounts and passwords remain/);const source=fs.readFileSync(path.join(__dirname,'../dist/game.js'),'utf8');assert.match(source,/ARE YOU SURE\? RESET ROUND/);assert.match(source,/gameResetConfirmation/);});

test('whole-round reset clears claimed quests and restores default progress',()=>{const g=game();g.run(fs.readFileSync(path.join(__dirname,'../dist/planets.js'),'utf8').replace('initializePlanetDirectory();setInterval(refreshSharedPlanets,15000);',''));g.run('state.questClaims={lightfactory:true,scans25:true};state.xp=900;state.waves.scans=[{type:"planet"}];var defaults=freshState();applySharedDirectory({userId:"admin",revision:2,resetGeneration:2,canEdit:true,planets:defaults.galaxy,structures:[],alliances:[defaults.alliance]})');assert.equal(g.run('Object.keys(state.questClaims).length'),0);assert.equal(g.run('state.xp'),0);assert.equal(g.run('state.waves.scans.length'),0);assert.doesNotMatch(g.run('questRows()'),/quest-title">✓ /);assert.doesNotMatch(g.run('questRows()'),/>CLAIMED</);});

test('population and government bonuses are additive and update active ship work without repricing',()=>{const g=game();g.run('state.buildings.lightFactory=1;state.buildings.mediumFactory=1;state.research.fighter=1;state.research.corvette=1;state.research.frigate=1');g.run('update=()=>save();state.production={id:Object.keys(SHIPS)[0],qty:10,total:100000,remaining:90000,cost:{metal:5000,crystal:3000,eonium:1000},factoryAssignments:{lightFactory:1,mediumFactory:0,heavyFactory:0}};state.workforce.shipwright=15;state.government="Socialism"');assert.equal(g.run('productionRate()'),Math.floor(115*1.35));const paid=g.run('JSON.stringify(state.production.cost)'),remaining=g.run('state.production.remaining');g.run('state.workforce.shipwright=40');assert.equal(g.run('productionRate()'),Math.floor(115*1.6));g.run('tickOnce()');assert.equal(g.run('state.production.remaining'),remaining-Math.floor(115*1.6));assert.equal(g.run('JSON.stringify(state.production.cost)'),paid);g.run('state.government="Nationalism";state.workforce.shipwright=0');assert.equal(g.run('productionRate()'),Math.floor(115*.9));});
test('government cost reduction charges new orders correctly and keeps existing orders paid prices',()=>{const g=game();g.run('state.buildings.lightFactory=1;state.buildings.mediumFactory=1;state.research.fighter=1;state.research.corvette=1;state.research.frigate=1');g.run('update=()=>save();state.government="Democracy";state.resources={metal:10000000,crystal:10000000,eonium:10000000};var id=Object.keys(SHIPS).find(id=>SHIPS[id].race==="Terran"&&SHIPS[id].class==="Fighter")');const id=g.run('id');g.document.getElementById('qty-'+id).value='10';const cost=g.run('JSON.stringify(shipProductionCost(id))');g.run('orderShips(id)');for(const [r,n] of Object.entries(JSON.parse(cost)))assert.equal(g.run('state.resources['+JSON.stringify(r)+']'),10000000-n*10);const paid=g.run('JSON.stringify(state.production.cost)');g.run('state.government="Totalitarianism"');assert.equal(g.run('JSON.stringify(state.production.cost)'),paid);assert.equal(g.run('governmentProduction().cost'),6);});
test('government formation and revolution apply manual production penalties with persistent lookup',()=>{const g=game();g.run('update=()=>save()');g.document.getElementById('governmentSelect').value='Socialism';g.run('saveGovernment()');assert.equal(g.run('currentGovernmentName()'),'Socialism');g.context.confirm=()=>false;g.document.getElementById('governmentSelect').value='Democracy';g.run('saveGovernment()');assert.equal(g.run('currentGovernmentName()'),'Socialism');g.context.confirm=()=>true;g.run('saveGovernment()');assert.equal(g.run('currentGovernmentName()'),'Anarchy');assert.equal(g.run('state.governmentRevolutionUntil-state.tick'),72);g.run('state.tick=state.governmentRevolutionUntil');assert.equal(g.run('currentGovernmentName()'),'Democracy');assert.match(g.run('governmentHTML()'),/Government|GOVERNMENT LOOKUP/);assert.equal(game(JSON.parse(g.store['starfall-round-v2'])).run('state.governmentPending'),'Democracy');});

test('quest rewards bank once, survive reload and accept resources once',()=>{const g=game();g.run('state.buildings.lightFactory=1;state.buildings.mediumFactory=1;state.research.fighter=1;state.research.corvette=1;state.research.frigate=1');g.run('update=()=>save();state.startupBonusGranted=true;var q=QUEST_CATEGORIES.flatMap(c=>c.quests).find(q=>q[3]==="building:lightFactory");claimQuest(q[0])');assert.equal(g.run('questBonusBank().metal'),500);g.run('claimQuest(q[0])');assert.equal(g.run('questBonusBank().metal'),500);const reloaded=game(JSON.parse(g.store['starfall-round-v2']));assert.equal(reloaded.run('questBonusBank().metal'),500);const before=g.run('state.resources.metal');g.run('allocateQuestBonus("accept")');assert.equal(g.run('state.resources.metal'),before+500);g.run('allocateQuestBonus("accept")');assert.equal(g.run('state.resources.metal'),before+500);assert.match(g.run('questRows()'),/REWARD/);});
test('bonus allocation validates the full budget and supports multiple research levels and partial buildings',()=>{const g=game();g.run('update=()=>save();questBonusBank().research=100000;questBonusBank().construction=700;state.research.fighter=1;var branch=TECH_TREE.find(t=>researchMax(t.id)>2).id;state.research[branch]=0;state.researchProgress[branch]=0;var needed=researchCost(branch,1)+researchCost(branch,2)');const branch=g.run('branch'),needed=g.run('needed');g.document.querySelectorAll=selector=>selector==='[data-bonus-rp]'?[{dataset:{bonusRp:branch},value:String(needed)}]:[{dataset:{bonusCu:'lightFactory'},value:'700'}];g.run('allocateQuestBonus("research")');assert.equal(g.run('state.research[branch]'),2);assert.equal(g.run('questBonusBank().research'),100000-needed);const before=g.run('state.buildings.lightFactory');g.run('allocateQuestBonus("construction")');assert.equal(g.run('state.buildings.lightFactory'),before+1);assert.equal(g.run('state.bonusConstructionProgress.lightFactory'),200);g.document.querySelectorAll=()=>[{dataset:{bonusCu:'lightFactory'},value:'1'}];g.run('allocateQuestBonus("construction")');assert.equal(g.run('state.bonusConstructionProgress.lightFactory'),200);});

test('startup bonus matches Planetarion base and race adjustments without repeat grants',()=>{const g=game();assert.equal(g.run('questBonusBank().metal'),2000000);assert.equal(g.run('questBonusBank().construction'),8750);assert.equal(g.run('questBonusBank().research'),7600);g.run('allocateQuestBonus("accept")');assert.equal(g.run('questBonusBank().metal'),0);const reloaded=game(JSON.parse(g.store['starfall-round-v2']));assert.equal(reloaded.run('questBonusBank().metal'),0);assert.equal(reloaded.run('questBonusBank().research'),7600);});

test('covert operations enforce protection, agents and research, charge once and produce filtered reports',()=>{const g=game();g.run('update=()=>save();state.resources={metal:100000,crystal:100000,eonium:100000};covertState().agents=30;var target=state.galaxy.find(p=>!p.player);target.roids={metal:6,crystal:6,eonium:6};target.covertAlert=0');g.document.getElementById('covertTarget').value=g.run('target.id');g.document.getElementById('covertOperation').value='fist';g.document.getElementById('covertSendAmount').value='9';g.run('executeCovert()');assert.equal(g.run('state.resources.metal'),100000);g.run('state.config.tickerPaused=false;state.config.tickerStopped=false;state.tick=25;covertState().stealth=80;Math.random=()=>.99;executeCovert()');assert.equal(g.run('state.resources.metal'),95500);assert.equal(g.run('totalRoids(target.roids)'),15);assert.equal(g.run('covertState().history.length'),1);assert.equal(g.run('state.news[0].category'),'COVERT_OPS');assert.equal(g.run('newsTintClass(state.news[0])'),'news-covert');g.run('state.newsCategories.COVERT_OPS=false;renderNews()');assert.doesNotMatch(g.elements.get('newsLog').innerHTML,/Covert operation Exploding/);g.document.getElementById('covertOperation').value='guards';g.run('executeCovert()');assert.equal(g.run('state.resources.metal'),95500);});
test('failed covert operations still charge and stealth recovers with wages on ticks',()=>{const g=game();g.run('update=()=>save();state.config.tickerPaused=false;state.config.tickerStopped=false;state.tick=25;state.resources={metal:100000,crystal:100000,eonium:100000};covertState().agents=20;covertState().stealth=80;var target=state.galaxy.find(p=>!p.player);target.covertAlert=200;Math.random=()=>.99');g.document.getElementById('covertTarget').value=g.run('target.id');g.document.getElementById('covertOperation').value='fist';g.document.getElementById('covertSendAmount').value='9';g.run('executeCovert()');assert.equal(g.run('covertState().history[0].success'),false);assert.equal(g.run('state.resources.metal'),95500);const stealth=g.run('covertState().stealth');g.run('tickCovert()');assert.ok(g.run('covertState().stealth')>stealth);assert.equal(g.run('state.resources.metal'),95480);});

test('fresh reset leaves all tax and scan sharing controls unchecked in one box',()=>{const g=game();assert.equal(g.run('state.userSettings.allianceTaxEnabled'),false);assert.equal(g.run('state.userSettings.allianceScansEnabled'),false);assert.equal(g.run('state.userSettings.shareScansToAll'),false);g.run('renderPlanetSettings()');const html=g.elements.get('planetSettingsContent').innerHTML;assert.equal((html.match(/class="quick-scan-sharing"/g)||[]).length,1);assert.doesNotMatch(html,/data-quick-setting="allianceTaxEnabled" checked/);assert.doesNotMatch(html,/data-quick-setting="allianceScansEnabled" checked/);});

test('full initial page boot renders covert, quests and news without late-constant errors',()=>{const g=game(undefined,true);assert.match(g.elements.get('covertContent').innerHTML,/OPERATION ORDERS/);assert.match(g.elements.get('questContent').innerHTML,/Temporal command/);assert.match(g.elements.get('newsLog').innerHTML,/news-log/);});
test('first ticker start, stop and restart unlock one-time asteroid rewards and game notices',()=>{const g=game();g.run('update=()=>save();controlTicker("start")');assert.equal(g.run('questValue("ticker:start")'),1);g.run('controlTicker("stop")');assert.equal(g.run('questValue("ticker:stop")'),1);assert.equal(g.run('state.config.tickerStopped'),true);g.run('controlTicker("start")');assert.equal(g.run('questValue("ticker:restart")'),1);assert.equal(g.run('state.news[0].category'),'GAME_UPDATES');g.run('state.startupBonusGranted=true;state.questBonuses={metal:0,crystal:0,eonium:0,research:0,construction:0,roids:{metal:0,crystal:0,eonium:0}};claimQuest("tickerFirstStart");claimQuest("tickerFirstStop");claimQuest("tickerFirstRestart");claimQuest("tickerFirstRestart")');assert.equal(g.run('questBonusBank().roids.metal'),3);assert.equal(g.run('questBonusBank().roids.crystal'),3);assert.equal(g.run('questBonusBank().roids.eonium'),3);assert.equal(g.run('questBonusBank().metal'),0);});

test('scheduled ticker starts once without unlocking any ticker quests',()=>{const g=game();g.run('update=()=>save();state.config.tickerPaused=true;state.config.tickerStopped=true;state.config.tickerAutoStartAt=Date.now()-100;processTickerAutoStart()');assert.equal(g.run('state.config.tickerPaused'),false);assert.equal(g.run('state.config.tickerAutoStartAt'),null);assert.equal(g.run('questValue("ticker:start")'),0);assert.equal(g.run('questValue("ticker:restart")'),0);assert.equal(g.run('state.news[0].category'),'GAME_UPDATES');const count=g.run('state.news.length');g.run('processTickerAutoStart()');assert.equal(g.run('state.news.length'),count);});

test('asteroid draft confirms atomically and preserves draft on insufficient resources',()=>{const g=game();g.run('update=()=>save();state.asteroidDraft={metal:2,crystal:3};state.resources={metal:100000,crystal:0,eonium:100000};confirmAsteroidDraft()');assert.equal(g.run('state.roids.metal'),6);assert.equal(g.run('state.resources.metal'),100000);assert.equal(g.run('state.asteroidDraft.metal'),2);const bill=g.run('asteroidDraftBill().metal');g.run('state.resources.crystal=100000;confirmAsteroidDraft()');assert.equal(g.run('state.roids.metal'),8);assert.equal(g.run('state.roids.crystal'),9);assert.equal(g.run('state.resources.metal'),100000-bill);assert.equal(g.run('Object.keys(state.asteroidDraft).length'),0);assert.match(g.run('miningCards()'),/ADD TO ORDER/);});

test('bulk quest claims include only completed unclaimed goals and do not duplicate rewards',()=>{const g=game();g.run('state.buildings.lightFactory=1;state.buildings.mediumFactory=1;state.research.fighter=1;state.research.corvette=1;state.research.frigate=1');g.run('update=()=>save();state.startupBonusGranted=true;claimCompletedQuests("defense")');const claims=g.run('Object.keys(state.questClaims).length'),bank=g.run('questBonusBank().metal');assert.ok(claims>0);g.run('claimCompletedQuests("defense")');assert.equal(g.run('questBonusBank().metal'),bank);assert.equal(g.run('Object.keys(state.questClaims).length'),claims);g.run('claimCompletedQuests()');assert.ok(g.run('Object.keys(state.questClaims).length')>=claims);assert.equal(g.run('state.questClaims.tickerFirstStart||false'),false);});

test('automatic claiming is opt-in and banks completed rewards only once',()=>{const g=game();assert.equal(g.run('state.userSettings.autoClaimQuests'),false);g.run('state.startupBonusGranted=true;state.userSettings.autoClaimQuests=true');assert.ok(g.run('autoClaimQuestRewards()')>0);const bank=g.run('questBonusBank().metal');assert.equal(g.run('autoClaimQuestRewards()'),0);assert.equal(g.run('questBonusBank().metal'),bank);assert.equal(g.run('state.questClaims.tickerFirstStart||false'),false);});

test('universe uses alliance labels only from enabled, permitted intel',()=>{const g=game();g.run('renderUniverse()');assert.equal(g.document.getElementById('universeAllianceFilter').hidden,true);g.run('state.universeIntelOverlay=true;state.universeIntelOwner=state.alliance.name;state.universeIntelRecords={"07:04:02":{targetAlliance:"Private Intel Label"}};renderUniverse()');assert.equal(g.document.getElementById('universeAllianceFilter').hidden,false);assert.match(g.document.getElementById('universeTable').innerHTML,/Private Intel Label/);assert.doesNotMatch(g.document.getElementById('universeTable').innerHTML,/>Vesper Pact</);g.run('state.universeIntelOverlay=false;renderUniverse()');assert.doesNotMatch(g.document.getElementById('universeTable').innerHTML,/Private Intel Label/);});
test('fleet appearance renames heroes and restores names without changing stats',()=>{const g=game();const original=g.run('JSON.stringify(SHIPS)');g.run('state.userSettings.trekFleetEnabled=true;state.userSettings.trekFleetPower="Federation";applyTrekFleetNames()');assert.match(g.run('shipCards()'),/HERO/);assert.match(g.run('shipCards()'),/USS/);const unchanged=g.run('Object.entries(SHIPS).every(([id,d])=>{const old=JSON.parse('+JSON.stringify(original)+')[id];return d.armour===old.armour&&d.damage===old.damage&&JSON.stringify(d.cost)===JSON.stringify(old.cost);})');assert.equal(unchanged,true);g.run('state.userSettings.trekFleetEnabled=false;applyTrekFleetNames()');assert.equal(g.run('JSON.stringify(SHIPS)'),original);});
test('fleet class transfers move only matching ships and clamp each group amount',()=>{const g=game();const ids=g.run('Object.keys(SHIPS).filter(id=>SHIPS[id].race===state.race&&SHIPS[id].class==="Fighter")');g.run('state.fleets.base=normalizeFleet({});state.fleets.f1=normalizeFleet({});update=()=>save()');g.run('state.fleets.base['+JSON.stringify(ids[0])+']=12');g.document.getElementById('transferShip').value='group:Fighter';g.document.getElementById('transferFrom').value='base';g.document.getElementById('transferTo').value='f1';g.document.getElementById('transferAmount').value='100';g.run('transferShips()');assert.equal(g.run('state.fleets.f1['+JSON.stringify(ids[0])+']'),12);assert.equal(g.run('state.fleets.base['+JSON.stringify(ids[0])+']'),0);});
test('central reset clears every enabled preference before syncing dirty local data',()=>{const g=game();g.run(fs.readFileSync(path.join(__dirname,'../dist/planets.js'),'utf8').replace('initializePlanetDirectory();setInterval(refreshSharedPlanets,15000);',''));g.run('state.userSettings.allianceTaxEnabled=true;state.userSettings.allianceScansEnabled=true;state.userSettings.shareScansToAll=true;state.userSettings.autoClaimQuests=true;var defaults=freshState();applySharedDirectory({userId:"admin",revision:3,resetGeneration:3,canEdit:true,planets:defaults.galaxy,structures:[],alliances:[defaults.alliance]})');for(const key of ['allianceTaxEnabled','allianceScansEnabled','shareScansToAll','autoClaimQuests'])assert.equal(g.run('state.userSettings.'+key),false);});
test('universe modules track real tick changes and hide alliances without intel',()=>{const g=game();g.run('renderUniverseModules()');assert.match(g.elements.get('universeModules').innerHTML,/TOP PLANETS/);assert.match(g.elements.get('universeModules').innerHTML,/TOP GALAXIES/);assert.doesNotMatch(g.elements.get('universeModules').innerHTML,/ALLIANCES · PRIVATE INTEL/);g.run('state.tick+=1;state.roids.metal+=3;renderUniverseModules()');assert.match(g.elements.get('universeModules').innerHTML,/\+3/);assert.equal(g.run('state.universeHistory.length'),2);g.run('state.universeIntelOverlay=true;state.universeIntelOwner=state.alliance.name;state.universeIntelRecords={"07:04:01":{targetAlliance:state.alliance.name}};renderUniverseModules()');assert.match(g.elements.get('universeModules').innerHTML,/ALLIANCES · PRIVATE INTEL/);});
test('overview identity follows current planet settings',()=>{const g=game();g.run('var home=state.galaxy.find(p=>p.player);home.name="Nova Prime";home.ruler="Admiral Sol";home.username="Star Captain";updateHomeCoordinates()');assert.equal(g.elements.get('homeHeroTitle').textContent,'Nova Prime, under your command.');assert.match(g.elements.get('homeHeroDescription').textContent,/Admiral Sol.*Star Captain/);assert.equal(g.elements.get('homeSceneName').textContent,'Nova Prime');});
test('every alliance structure waits three ticks and charges only once',()=>{for(const type of ['transwarpHub','dysonSphere','ancientWeapons','voyagerIV','solarFlares']){const g=game();g.run('update=()=>save();state.alliance.fortress.strongholdGalaxy="07:04";state.alliance.tax=10;state.alliance.fund={metal:10000000,crystal:10000000,eonium:10000000}');const before=g.run('state.alliance.fund.metal');g.run('queueAllianceStructure('+JSON.stringify(type)+',11)');const paid=g.run('state.alliance.fund.metal');assert.ok(paid<before);g.run('queueAllianceStructure('+JSON.stringify(type)+',12)');assert.equal(g.run('state.alliance.fund.metal'),paid);assert.equal(g.run('state.alliance.structures.active.length'),0);g.run('state.tick+=2;processAllianceStructures()');assert.equal(g.run('state.alliance.structures.active.length'),0);assert.equal(g.run('state.alliance.structures.buildQueue.length'),1);g.run('state.tick+=1;processAllianceStructures()');assert.equal(g.run('state.alliance.structures.buildQueue.length'),0);if(['voyagerIV','solarFlares'].includes(type))assert.equal(g.run('state.structurePlanets.some(p=>p.building)'),false);else assert.equal(g.run('state.alliance.structures.active.some(p=>p.type==='+JSON.stringify(type)+')'),true);g.run('renderOverviewAllianceStructures()');assert.match(g.elements.get('overviewAllianceStructures').innerHTML,/ALLIANCE STRUCTURES/);}});
test('renaming a commander does not lose the account-owned alliance rank',()=>{const g=game();g.run('var home=state.galaxy.find(p=>p.player),member=state.alliance.members.find(m=>m.planet===home.name);member.planetId=home.id;home.name="Nova Prime";member.planet="Nova Prime";member.name="Star Captain"');assert.equal(g.run('currentAllianceRank()'),'HC');assert.equal(g.run('mayAlliance("structures")'),true);});

test('Admin Controlcenter combines configuration, ticker and snapshot controls without duplicate ids',()=>{const g=game();g.run('window.isGameAdmin=true;window.useLegacyStaffView=true;window.scrollTo=()=>{};navigate("adminControl")');const html=g.elements.get('adminContent').innerHTML;assert.equal(g.elements.get('adminPageHeading').textContent,'Admin Controlcenter');for(const label of ['ROUND CONFIGURATION','ADVANCED ROUND STATE','round-state-reset'])assert.ok(html.includes(label));const ids=[...html.matchAll(/id="([^"\s]+)"/g)].map(m=>m[1]);assert.equal(new Set(ids).size,ids.length);});

test('delayed launches wait, cancel safely and fake defence recalls at ETA one',()=>{const g=game();g.run('update=()=>save();state.fleets.f1=normalizeFleet({"terran-lumen":10})');for(const [id,val] of [['missionFleet','f1'],['missionTarget',g.run('state.galaxy.find(p=>!p.player).id')],['missionType','Fake Defence'],['missionDelay','3']])g.document.getElementById(id).value=val;const count=g.run('totalShips(state.fleets.f1)');g.run('launchMission();tickOnce();tickOnce()');assert.equal(g.run('state.missions[0].phase'),'scheduled');g.run('recallMission(state.missions[0].id)');assert.equal(g.run('state.missions.length'),0);assert.equal(g.run('totalShips(state.fleets.f1)'),count);g.document.getElementById('missionDelay').value='0';g.run('launchMission();tickOnce();tickOnce();tickOnce();tickOnce()');assert.equal(g.run('state.missions[0].phase'),'returning');assert.ok(g.run('state.missions[0].eta')>0);});
test('fleet names validate and persist without changing fleet ids',()=>{const g=game();g.run('update=()=>save()');for(const [i,name] of ['Alpha','Beta','Gamma'].entries())g.document.getElementById('fleetName-f'+(i+1)).value=name;g.run('renamePlayerFleets()');assert.equal(g.run('fleetLabel("f1")'),'Alpha');assert.equal(game(JSON.parse(g.store['starfall-round-v2'])).run('fleetLabel("f1")'),'Alpha');g.document.getElementById('fleetName-f2').value='Alpha';g.run('renamePlayerFleets()');assert.equal(g.run('fleetLabel("f2")'),'Beta');});
test('vendor locks ships for twelve ticks, pays once and cancellation returns after twelve ticks',()=>{const g=game();g.run('update=()=>save();state.fleets.base["terran-lumen"]=10');g.document.getElementById('saleShip').value='terran-lumen';g.document.getElementById('saleQuantity').value='4';const value=g.run('playerValue()');g.run('sellPlayerShips()');assert.equal(g.run('state.fleets.base["terran-lumen"]'),6);assert.equal(g.run('playerValue()'),value);g.run('state.tick+=11;settleShipSales()');assert.equal(g.run('state.shipSales.length'),1);const money=g.run('state.resources.metal'),quote=g.run('state.shipSales[0].quote.metal');g.run('state.tick++;settleShipSales();settleShipSales()');assert.equal(g.run('state.resources.metal'),money+quote);g.run('sellPlayerShips();cancelShipSale(state.shipSales[0].id);state.tick+=11;settleShipSales()');assert.equal(g.run('state.fleets.base["terran-lumen"]'),2);g.run('state.tick++;settleShipSales()');assert.equal(g.run('state.fleets.base["terran-lumen"]'),6);});
test('government economy bonuses update output and revolution applies Anarchy penalties',()=>{const g=game();g.run('state.workforce.research=20;state.workforce.construction=20');const mining=g.run('grossIncome().metal'),research=g.run('researchRate()'),build=g.run('constructionRate()');g.run('state.government="Corporatism"');assert.ok(g.run('grossIncome().metal')>mining);assert.ok(g.run('researchRate()')<research);assert.ok(g.run('constructionRate()')<build);g.run('state.governmentPending="Socialism";state.governmentRevolutionUntil=state.tick+72');assert.equal(g.run('governmentEconomyBonus("mining")'),-25);});
test('fleet travel follows class, research and in-galaxy defence rules',()=>{const g=game();assert.equal(g.run('fleetTravelTime({"terran-lumen":1},{coords:"08:01:01"},"Attack")'),12);assert.equal(g.run('fleetTravelTime({"terran-solstice":1},{coords:"08:01:01"},"Attack")'),14);g.run('state.research.travel=4');assert.equal(g.run('fleetTravelTime({"terran-lumen":1},{coords:"08:01:01"},"Attack")'),8);assert.equal(g.run('fleetTravelTime({"terran-solstice":1},{coords:homeGalaxy()+":02"},"Defence")'),5);});

test('fourth fleet is permanent and can only launch with Launch Bay permission',()=>{const g=game();g.run('update=()=>save();state.fleets.f4["terran-lumen"]=5');assert.equal(g.run('fleetLabel("f4")'),'Alliance Fleet');assert.equal(g.run('defaultAlliancePermissions().Officer.launchBay'),true);assert.equal(g.run('defaultAlliancePermissions().Member.launchBay'),false);for(const [id,value] of [['missionFleet','f4'],['missionTarget',g.run('state.galaxy.find(p=>!p.player).id')],['missionType','Defence']])g.document.getElementById(id).value=value;g.run('launchMission()');assert.equal(g.run('state.missions.length'),0);g.run('launchMission(true)');assert.equal(g.run('state.missions[0].fleet'),'f4');assert.equal(g.run('state.fleets.f4["terran-lumen"]'),0);g.run('recallMission(state.missions[0].id);tickOnce()');assert.equal(g.run('state.fleets.f4["terran-lumen"]'),5);});

test('staff centers have separate subpages and planet membership moves to alliance administration',()=>{const g=game();g.context.isGameAdmin=true;g.run('window.isGameAdmin=true;window.useLegacyStaffView=true;window.scrollTo=()=>{};navigate("adminAlliances")');assert.equal(g.elements.get('adminPageHeading').textContent,'Alliance Controlcenter');assert.match(g.elements.get('adminContent').innerHTML,/data-admin-alliance-page="members"/);g.run('adminAlliancePage="members";renderAdminAllianceCenter()');assert.match(g.elements.get('adminContent').innerHTML,/APPLY MEMBERSHIP/);g.run('navigate("adminMultihunters")');assert.match(g.elements.get('adminContent').innerHTML,/PLACEHOLDER/);g.run('navigate("adminPlanets")');assert.doesNotMatch(g.elements.get('adminContent').innerHTML,/data-planet-module="alliance"/);assert.match(g.elements.get('adminContent').innerHTML,/data-admin-tab="ships"/);});

test('automatic claiming reports persistent confirmation and links to bonus allocation',()=>{const g=game();g.run('state.userSettings.autoClaimQuests=true;state.startupBonusGranted=true;autoClaimQuestRewards();renderPlanetSettings()');const count=g.run('state.questAutomationStats.total');assert.ok(count>0);assert.match(g.elements.get('planetSettingsContent').innerHTML,/AUTOMATIC CLAIMING ON/);assert.match(g.elements.get('planetSettingsContent').innerHTML,/Last claim:/);assert.match(g.elements.get('planetSettingsContent').innerHTML,/data-goto="quests" data-open-achievement-bonuses/);g.run('autoClaimQuestRewards()');assert.equal(g.run('state.questAutomationStats.total'),count);g.run('window.isGameAdmin=true;window.useLegacyStaffView=true;window.scrollTo=()=>{};openAchievementBonuses()');assert.equal(g.run('state.questView'),'bonuses');});

test('round control workspace removes duplicate speed, step and section navigation controls',()=>{const g=game();g.run('window.isGameAdmin=true;adminTab="control";renderAdmin()');const html=g.elements.get('adminContent').innerHTML;assert.match(html,/id="admin-round-control"/);assert.doesNotMatch(html,/href="#admin-center-settings"|href="#admin-center-runtime"|id="tickerMinutes"|data-admin="advance"|data-ticker="speed"/);assert.equal((html.match(/data-ticker="step"/g)||[]).length,1);assert.equal((html.match(/id="admTickHours"/g)||[]).length,1);});

test('Add to Calc loads ready and deployed fleet ships and preserves defender input',()=>{const g=game();g.run('window.isGameAdmin=true;window.useLegacyStaffView=true;window.scrollTo=()=>{};window.bcalc={a:{},d:{"terran-aegis":7}};state.fleets.f1=normalizeFleet({"terran-lumen":5});state.missions=[{fleet:"f1",ships:{"terran-lumen":3}}];addFleetToCalc("f1")');assert.equal(g.run('window.bcalc.a["terran-lumen"]'),8);assert.equal(g.run('window.bcalc.d["terran-aegis"]'),7);assert.equal(g.run('allianceTab'),'bcalc');assert.match(g.run('fleetRosterHTML()'),/data-fleet-to-calc="f4"/);});
test('Classic is a valid game skin and Network Hub respects the intel toggle',()=>{const g=game();assert.equal(g.run('UI_THEME_VALUES.includes("Classic")'),true);g.run('state.userSettings.networkIntel=false;state.alliance.calls=[{planet:state.galaxy[1].name,coords:state.galaxy[1].coords,eta:3,attackerCount:25}];renderNetworkHub()');assert.doesNotMatch(g.elements.get('networkHubContent').innerHTML,/<b>Alliance threat report<\/b>/);g.run('state.userSettings.networkIntel=true;renderNetworkHub()');assert.match(g.elements.get('networkHubContent').innerHTML,/<b>Alliance threat report<\/b>/);g.run('state.alliance.rankPermissions={HC:{intel:false}};renderNetworkHub()');assert.doesNotMatch(g.elements.get('networkHubContent').innerHTML,/<b>Alliance threat report<\/b>/);});
test('fleet launch and combat capture persist separate movement reports',()=>{const g=game();g.run('update=()=>save();state.config.protectionTicks=0;state.centralResetGeneration=2;state.fleets.f1={"terran-wayfarer":20};');g.document.getElementById('missionFleet').value='f1';g.document.getElementById('missionTarget').value=g.run('state.galaxy.find(p=>!p.player&&p.alliance!==state.alliance.name).id');g.document.getElementById('missionType').value='Attack';g.document.getElementById('missionDelay').value='0';g.run('launchMission()');assert.equal(g.run('state.movementAuditQueue[0].ships'),20);assert.equal(g.run('state.movementAuditQueue[0].generation'),2);g.run('const auditMission=state.missions[0];queueMovementReport(auditMission,"result",{captured:4,attackerLost:0,defenderLost:2});');assert.equal(g.run('state.movementAuditQueue.length'),2);assert.equal(g.run('state.movementAuditQueue[1].captured'),4);});
test('staff structure generation reserves valid slots and supports three tick builds and timed activation',()=>{const g=game();g.run('window.isGameAdmin=true;window.useLegacyStaffView=true;const staffAlliance=copy(state.alliance);staffAlliance.name="Other Guild";staffAlliance.structures={active:[],buildQueue:[],cooldowns:{},history:[]};staffAlliance.fortress.strongholdGalaxy=homeGalaxy();const generated=staffStructureDraft(staffAlliance,"dysonSphere",homeGalaxy(),11,false);');assert.equal(g.run('generated.planet.alliance'),'Other Guild');assert.equal(g.run('generated.planet.building'),true);assert.equal(g.run('generated.build.completesAt-generated.build.startedAt'),3);g.run('state.structurePlanets.push(generated.planet)');assert.throws(()=>g.run('staffStructureDraft(staffAlliance,"ancientWeapons",homeGalaxy(),11,false)'),/occupied/);assert.throws(()=>g.run('staffStructureDraft(staffAlliance,"ancientWeapons",homeGalaxy(),10,false)'),/valid structure/);assert.equal(g.run('staffStructureDraft(staffAlliance,"ancientWeapons",homeGalaxy(),12,true).effect.expiresAt-state.tick'),4);assert.throws(()=>g.run('staffStructureDraft(staffAlliance,"voyagerIV",homeGalaxy(),12,true)'),/3-tick/);g.run('window.isGameAdmin=false');assert.throws(()=>g.run('staffStructureDraft(staffAlliance,"dysonSphere",homeGalaxy(),12,false)'),/Staff access/);});
test('simulated uplink battle creates reports and calculator inputs without changing real assets or movement audit',()=>{const g=game();g.run('update=()=>save();const realAssets=JSON.stringify({fleets:state.fleets,resources:state.resources,roids:state.roids,galaxy:state.galaxy,movementAuditQueue:state.movementAuditQueue});const simReport=simulateUplinkBattle();');assert.equal(g.run('state.uplinkTestBattles.length'),1);assert.equal(g.run('simReport.simulated'),true);assert.equal(g.run('state.news[0].battleReport'),undefined);assert.equal(g.run('JSON.stringify({fleets:state.fleets,resources:state.resources,roids:state.roids,galaxy:state.galaxy,movementAuditQueue:state.movementAuditQueue})===realAssets'),true);g.run('navigate=()=>{};openBattleNews(simReport.id)');assert.equal(g.run('JSON.stringify(window.bcalc.a)===JSON.stringify(simReport.attacker)'),true);assert.equal(g.run('JSON.stringify(window.bcalc.d)===JSON.stringify(simReport.defender)'),true);});
test('normal administration routes open portal staff while legacy view remains selectable',()=>{const g=game();g.run('window.isGameAdmin=true;window.useLegacyStaffView=false;navigate("adminAlliances")');assert.equal(g.run('location.href'),'/staff.html#alliances');g.run('window.useLegacyStaffView=true;window.isGameAdmin=true;window.useLegacyStaffView=true;window.scrollTo=()=>{};navigate("adminAlliances")');assert.equal(g.run('adminTab'),'alliances');});
test('calculator fake news is restricted to calculator output and never added to Journal',()=>{const g=game();g.run('const beforeCalc=JSON.stringify({news:state.news,fleets:state.fleets,resources:state.resources});const calcFight=resolveCombat({"terran-lumen":20},{"terran-aegis":8});const calcReport=recordSimulatedCalculatorReport(calcFight,"Training combat");');assert.equal(g.run('calcReport.simulated'),true);assert.equal(g.run('calcReport.source'),'calculator');assert.equal(g.run('window.bcalcReport.id'),g.run('calcReport.id'));assert.equal(g.run('JSON.stringify({news:state.news,fleets:state.fleets,resources:state.resources})===beforeCalc'),true);});
test('reset stops ticker and clears prior schedules until an explicit manual or timed start',()=>{const g=game();g.run('update=()=>save();state.config.tickerAutoStartAt=Date.now()-1000;resetTickerAfterRoundReset();state.nextTickAt=Date.now()-10000;updateCountdown()');assert.equal(g.run('state.tick'),1);assert.equal(g.run('state.config.tickerStopped'),true);assert.equal(g.run('state.config.tickerAutoStartAt'),null);g.run('controlTicker("start")');assert.equal(g.run('state.config.tickerPaused'),false);g.run('resetTickerAfterRoundReset();state.config.tickerAutoStartAt=Date.now()-1;processTickerAutoStart()');assert.equal(g.run('state.config.tickerPaused'),false);});

test('fresh state ticker is stopped and has no inherited start schedule',()=>{const g=game();assert.equal(g.run('state.config.tickerStopped'),true);assert.equal(g.run('state.config.tickerPaused'),true);assert.equal(g.run('state.config.tickerAutoStartAt'),null);});

test('alliance readiness table preserves target columns and shows same-galaxy ETA five',()=>{const g=game();g.run('SHIPS["terran-lumen"].targetSlots=["Corvette","","Battleship"]');const html=g.run('allianceReadinessTable({"terran-lumen":24},{coords:"07:04:02",allianceEta:{"terran-lumen":11}})');assert.match(html,/<td>Corvette<\/td><td><\/td><td>Battleship<\/td><td>5<\/td>/);assert.match(html,/>Class<\/th>/);const other=g.run('allianceReadinessTable({"terran-lumen":24},{coords:"08:04:02",allianceEta:{"terran-lumen":11}})');assert.match(other,/<td>11<\/td>/);const unknown=g.run('allianceReadinessTable({"terran-lumen":24},{coords:"08:04:02"})');assert.match(unknown,/<td>Battleship<\/td><td><\/td>/);});

test('alliance fleet is first, player fleets are collapsed and mission fleets are omitted',()=>{const g=game();const html=g.run('allianceMemberFleetSlots({planetId:"home",coords:"07:04:01",fleets:{base:{"terran-lumen":99},f1:{"terran-lumen":10},f2:{"terran-lumen":6},f3:{},f4:{"terran-lumen":4}},awaySlots:["f2"]},false)');assert.ok(html.indexOf('Alliance Fleet')<html.indexOf('Fleet 1'));assert.match(html,/data-fleet-fold="home:f1" >/);assert.doesNotMatch(html,/Fleet 2|Base fleet|>99</);assert.match(html,/Fleet 3/);assert.doesNotMatch(html,/data-fleet-fold="home:f1" open/);});

test('ticker information confirms actions and distinguishes stopped paused running',()=>{const g=game();assert.match(g.run('tickerStatusHTML()'),/STOPPED/);g.run('update=()=>save();controlTicker("start")');assert.match(g.run('tickerStatusHTML()'),/RUNNING|Ticker started/);assert.equal(g.run('state.tickerLastAction.message'),'Ticker started. Automatic ticks are enabled.');g.run('controlTicker("pause")');assert.match(g.run('tickerStatusHTML()'),/PAUSED/);g.run('controlTicker("stop")');assert.match(g.run('tickerStatusHTML()'),/STOPPED/);assert.match(g.run('state.tickerLastAction.message'),/disabled/);});

test('new round population management starts at zero with no research progress',()=>{const g=game();assert.equal(g.run('freshState().research.population'),0);assert.equal(g.run('freshState().researchActive'),null);assert.equal(g.run('Object.keys(freshState().researchProgress).length'),0);});

test('workforce pool grows with research and enforces per-department caps',()=>{const g=game();assert.equal(g.run('workforceAllocationLimit()'),50);assert.equal(g.run('Object.values(freshState().workforce).reduce((n,v)=>n+v,0)'),0);assert.equal(g.run('validWorkforceAssignments({mining:25,research:25,construction:0,shipwright:0,security:0})'),true);assert.equal(g.run('validWorkforceAssignments({mining:26,research:24,construction:0,shipwright:0,security:0})'),false);assert.equal(g.run('validWorkforceAssignments({mining:25,research:25,construction:1,shipwright:0,security:0})'),false);g.run('state.research.population=1');assert.equal(g.run('questValue("workforceCapacity")'),60);g.run('state.research.population=3');assert.equal(g.run('questValue("workforceCapacity")'),80);g.run('state.research.population=5');assert.equal(g.run('workforceAllocationLimit()'),100);assert.equal(g.run('validWorkforceAssignments({mining:25,research:50,construction:25,shipwright:0,security:0})'),true);assert.equal(g.run('validWorkforceAssignments({mining:0,research:0,construction:36,shipwright:0,security:0})'),false);assert.equal(g.run('validWorkforceAssignments({mining:0,research:0,construction:0,shipwright:61,security:0})'),false);assert.equal(g.run('validWorkforceAssignments({mining:0,research:0,construction:0,shipwright:0,security:51})'),false);});

test('confirmed orders save before reloading and failed orders do not reload',()=>{const g=game();let reloads=0;g.context.location.reload=()=>{reloads++;assert.ok(g.store['starfall-round-v2']);};g.run('update=()=>save();state.resources={metal:0,crystal:0,eonium:0};state.asteroidDraft={metal:1};confirmAsteroidDraft()');assert.equal(reloads,0);g.run('state.resources.metal=100000;confirmAsteroidDraft()');assert.equal(reloads,1);assert.equal(JSON.parse(g.store['starfall-round-v2']).asteroidDraft.metal,undefined);assert.equal(JSON.parse(g.store['starfall-round-v2']).roids.metal,7);});
test('adding a draft does not trigger a page reload',()=>{const g=game();let reloads=0;g.context.location.reload=()=>reloads++;g.document.getElementById('mine-metal').value='1';g.run('addAsteroidDraft("metal")');assert.equal(reloads,0);assert.equal(g.run('state.asteroidDraft.metal'),1);});

