test('fleet roster lists actual ship names with class and deployed ships',()=>{const g=game();g.run('state.fleets.base=normalizeFleet({"terran-lumen":24,"terran-aegis":10});state.fleets.f1=normalizeFleet({"terran-lumen":10});state.missions=[{fleet:"f1",ships:{"terran-aegis":4},phase:"outbound",eta:3,targetName:"Target"}]');const html=g.run('fleetRosterHTML()');assert.match(html,/<td>Lumen<\/td><td>Fighter<\/td><td>Corvette<\/td><td><\/td><td><\/td><td><\/td><td class="fleet-quantity">24<\/td><td class="fleet-quantity">10<\/td>/);assert.match(html,/<td>Aegis<\/td><td>Corvette<\/td><td>Fighter<\/td><td><\/td><td><\/td><td><\/td><td class="fleet-quantity">10<\/td><td class="fleet-quantity">4<\/td>/);assert.match(html,/outbound.*ETA 3/);assert.match(html,/data-fleet-to-calc="f4"/);});

test('claim receipts list earned achievements and exact reward totals without double grants',()=>{const g=game();g.run('update=()=>save();questBonusBank();state.tickerQuestFlags={stop:true};var bankBefore=JSON.parse(JSON.stringify(questBonusBank()));claimCompletedQuests()');const receipt=g.run('state.news[0].achievementReceipt');assert.ok(receipt.entries.length>0);assert.equal(receipt.medals,receipt.entries.length);const before=g.run('bankBefore'),after=g.run('questBonusBank()');for(const k of ['metal','crystal','eonium','research','construction'])assert.equal(after[k]-before[k],receipt.totals[k]);for(const k of ['metal','crystal','eonium'])assert.equal(after.roids[k]-before.roids[k],receipt.totals.roids[k]);assert.match(g.run('achievementReceiptHTML(state.news[0].achievementReceipt)'),/Achievements claimed|TOTAL REWARDS CLAIMED|Gold claim medal/);const saved=g.run('JSON.stringify(questBonusBank())');g.run('claimCompletedQuests()');assert.equal(g.run('JSON.stringify(questBonusBank())'),saved);});

test('36 planetary worlds bound starting population and always change on reset',()=>{const g=game();assert.equal(g.run('PLANET_TYPES.filter(t=>t.family==="Original").length'),20);assert.equal(g.run('new Set(PLANET_TYPES.map(t=>t.id)).size'),g.run('PLANET_TYPES.length'));assert.ok(g.run('PLANET_TYPES.filter(t=>t.family==="Original").every(t=>t.basePopulation>=500&&t.basePopulation<=1000&&t.basePopulation===500+t.habitability*5)'));assert.ok(g.run('PLANET_TYPES.some(t=>t.growthPercent<0)&&PLANET_TYPES.some(t=>t.growthPercent>0)'));for(let i=0;i<60;i++)assert.notEqual(g.run('rollPlanetType("planet-01").id'),'planet-01');assert.equal(g.run('freshState("planet-01").config.tickerStopped'),true);});
test('Biodome growth combines world and research modifiers, carries fractions and never fills instantly',()=>{const g=game();g.run('state.planetType="planet-33";state.population=500;state.buildings.biodome=1;state.research.demography=0;state.populationGrowthCarry=0');assert.equal(g.run('populationGrowthRate()'),.25);for(let i=0;i<3;i++)g.run('growColonyPopulation()');assert.equal(g.run('state.population'),500);g.run('growColonyPopulation()');assert.equal(g.run('state.population'),501);g.run('state.research.demography=5');assert.equal(g.run('populationGrowthRate()'),.5);g.run('state.population=549;state.populationGrowthCarry=.9;growColonyPopulation()');assert.equal(g.run('state.population'),550);assert.equal(g.run('state.populationGrowthCarry'),0);g.run('state.buildings.biodome=0;state.population=499;growColonyPopulation()');assert.equal(g.run('state.population'),499);});
test('new research and population quests belong to Development with defined balanced receipts',()=>{const g=game();assert.equal(g.run('researchMax("demography")'),5);assert.equal(g.run('researchCost("demography",5)'),4800);assert.equal(g.run('QUEST_CATEGORIES.find(c=>c.id==="development").quests.filter(q=>q[3]==="research:demography"||q[3]==="population").length'),10);assert.equal(g.run('questReward(["x","",3000,"population"]).construction'),800);assert.equal(g.run('questReward(["x","",5,"research:demography"]).research'),600);assert.equal(g.run('UI_THEME_VALUES.includes("AstraNexus")'),true);});

test('all news entries gain lore while retaining factual reports and captured colony context',()=>{const g=game();g.run('addNews("Galaxy vote recorded.","good")');assert.equal(g.run('state.news[0].context.population'),g.run('state.population'));const html=g.run('newsEventCard(state.news[0],0)');assert.match(html,/Galaxy vote recorded/);assert.match(html,/Electoral registrar/);assert.match(html,/COLONY SNAPSHOT/);assert.match(html,/Population mining bonus/);assert.match(g.run('newsEventCard({text:"Legacy event",type:"info",tick:1},1)'),/COMMAND ATMOSPHERE/);});

test('expanded offices offer at least fifteen valid goals, ordered civic to military to intelligence',()=>{const g=game();assert.ok(g.run('QUEST_CATEGORIES.every(c=>c.quests.length>=15&&c.quests.every(q=>q[2]>0&&q[3]!=="offsite"))'));assert.equal(g.run('QUEST_CATEGORIES[0].id'),'education');assert.equal(g.run('new Set(QUEST_CATEGORIES.flatMap(c=>c.quests.map(q=>q[0]))).size'),g.run('QUEST_CATEGORIES.reduce((n,c)=>n+c.quests.length,0)'));});
test('locked and capacity-blocked free buildings convert to CU, settlement rewards respect housing',()=>{const g=game();g.run('state.research.fighter=0;state.buildings.lightFactory=0;var locked=resolveQuestReward({structures:{lightFactory:1}})');assert.equal(g.run('locked.construction'),500);assert.equal(g.run('Object.keys(locked.structures).length'),0);g.run('state.research.fighter=1;var unlocked=resolveQuestReward({structures:{lightFactory:1}})');assert.equal(g.run('unlocked.structures.lightFactory'),1);g.run('state.population=populationCapacity();questBonusBank().population=10;allocateQuestBonus("accept")');assert.equal(g.run('questBonusBank().population'),10);});
test('Arrakis travel modifier applies to same-galaxy defence and ordinary missions, never below one',()=>{const g=game();g.run('state.planetType=PLANET_TYPES.find(t=>t.name==="Arrakis").id;var destination={coords:homeGalaxy()+":02",alliance:"Other"}');assert.equal(g.run('fleetTravelTime({},destination,"Defence")'),4);assert.equal(g.run('fleetTravelTime({},destination,"Attack")'),g.run('fleetBaseTravelTime({},destination,"Attack")')-1);});
test('special worlds have unique names, bounded founding premiums and theme entitlement',()=>{const g=game();assert.equal(g.run('PLANET_TYPES.filter(t=>["Borg","Undine"].includes(t.family)).length'),20);assert.ok(g.run('PLANET_TYPES.filter(t=>["Borg","Undine"].includes(t.family)).every(t=>t.basePopulation>1000&&t.basePopulation<=1050&&t.populationBoostPercent>=.05&&t.populationBoostPercent<=5&&t.uniquePerRound)'));assert.equal(g.run('visibleWorldThemes().some(([id])=>id==="UltimateWorld")'),false);g.run('state.planetType=PLANET_TYPES.find(t=>t.name==="Arrakis").id');assert.equal(g.run('visibleWorldThemes().some(([id])=>id==="UltimateWorld")'),true);assert.equal(g.run('displayPlanetName("Of locutus")'),'locutus');});

test('ordinary low-habitability worlds leave selection while unique Arrakis remains',()=>{const g=game();assert.ok(g.run('PLANET_TYPES.filter(t=>t.family==="Original").every(t=>t.habitability>60)'));assert.ok(g.run('PLANET_TYPES.some(t=>t.name==="Arrakis"&&t.habitability<60&&t.uniquePerRound)'));g.run('state.planetType="planet-36"');assert.ok(g.run('planetBasePopulation(state)>=500'));});

test('ancestral world discounts multiply government prices and ordinary worlds retain their prices',()=>{const g=game();g.run('state.government="Democracy";state.planetType="planet-01"');const base=g.run('shipProductionCost("terran-lumen").metal');g.run('state.planetType="race-homeworld-terran"');assert.equal(g.run('shipProductionCost("terran-lumen").metal'),g.run('Math.ceil(SHIPS["terran-lumen"].cost.metal*(1-governmentProduction().cost/100)*.9)'));assert.ok(g.run('shipProductionCost("terran-lumen").metal')<base);const worlds=g.run('PLANET_TYPES.filter(t=>t.family==="RaceHomeworld")');assert.equal(worlds.length,5);assert.ok(worlds.every(t=>t.uniquePerRound&&t.rarity==='Ultimate'&&t.shipCostDiscountPercent===10));});

test('error history is never re-dated or reported as a current-page error',()=>{const source=fs.readFileSync(path.join(__dirname,'../dist/error-log.js'),'utf8'),store={'starfall-error-log':JSON.stringify(['2026-10-14T11:51:37.647Z · 2026-10-14T11:05:10.812Z · Failed to load LINK'])};function context(){const selectors=new Map();const element=()=>({className:'',innerHTML:'',textContent:'',hidden:false,append(){},querySelector(s){if(!selectors.has(s))selectors.set(s,element());return selectors.get(s);}}),c=vm.createContext({location:{pathname:'/portal.html'},URL,document:{createElement:element,body:element(),head:element()},sessionStorage:{getItem:k=>store[k],setItem:(k,v)=>store[k]=v},addEventListener(){}});c.window=c;vm.runInContext(source,c);return c;}const first=context();assert.equal(first.starfallErrorLog.text(),'');assert.equal(first.starfallErrorLog.current().length,0);first.starfallErrorLog.record('New runtime failure');const saved=JSON.parse(store['starfall-error-log']);assert.equal(saved[0].at,'2026-10-14T11:05:10.812Z');assert.equal(saved[0].message,'Failed to load LINK');const second=context();assert.equal(second.starfallErrorLog.text(),'');assert.deepEqual(JSON.parse(store['starfall-error-log']),saved);});

test('bonus RP completes the active level and releases its slot while retaining partial next-level progress',()=>{const g=game();g.run('update=()=>save();var branch=TECH_TREE.find(t=>researchMax(t.id)>2).id;state.research[branch]=0;state.researchProgress[branch]=20;state.researchActive=branch;questBonusBank().research=100000;var needed=researchCost(branch,1)-20+7');const branch=g.run('branch'),needed=g.run('needed');g.document.querySelectorAll=()=>[{dataset:{bonusRp:branch},value:String(needed)}];g.run('allocateQuestBonus("research")');assert.equal(g.run('state.research[branch]'),1);assert.equal(g.run('state.researchActive'),null);assert.equal(g.run('state.researchProgress[branch]'),7);assert.equal(g.run('questBonusBank().research'),100000-needed);});
test('galaxy politics candidates include own planet and exclude foreign rulers and stale offices',()=>{const g=game();g.run('state.galaxy=[{id:"staff",ruler:"Paul",name:"Staff",coords:"01:01:01"},{id:"own",ruler:"LordCharles",name:"Colony",coords:"01:02:01",player:true},{id:"peer",ruler:"Local",name:"Peer",coords:"01:02:02"}];state.politics={gc:"Paul",votes:{Paul:3,Local:1},ministers:{development:"Paul",war:"Local"},trust:{staff:"trusted"},votesToExile:[],allowedFund:{}};state.politicsGalaxy=null;renderPolitics()');const html=g.elements.get('politicsContent').innerHTML;assert.doesNotMatch(html,/Paul/);assert.match(html,/<option>LordCharles<\/option>/);assert.equal((html.match(/<option>Local<\/option>/g)||[]).length,1);assert.equal(g.run('state.politics.gc'),'');assert.equal(g.run('state.politics.ministers.development'),undefined);assert.equal(g.run('Object.keys(state.politics.trust).length'),0);g.document.getElementById('gcVote').value='Paul';const before=g.run('JSON.stringify(state.politics)');g.run('politicsAction("vote")');assert.equal(g.run('JSON.stringify(state.politics)'),before);});
test('moving planet switches galaxy identity and rejects departed offices without losing other galaxy identity',()=>{const g=game();g.run('state.galaxy=[{id:"own",ruler:"Actual Ruler",name:"Home",coords:"01:02:01",player:true},{id:"peer",ruler:"Peer",name:"Peer",coords:"01:02:02"}];state.politics={gc:"Actual Ruler",votes:{"Actual Ruler":1},ministers:{economics:"Actual Ruler"},banner:"Second Galaxy",message:"Second message",trust:{},votesToExile:[],allowedFund:{}};state.politicsGalaxy=null;ensureGalaxyPolitics();movePlanet(state.galaxy[0],"01:03:01");renderPolitics()');assert.equal(g.run('state.politics.gc'),'');assert.equal(g.run('state.politics.message'),'');assert.doesNotMatch(g.elements.get('politicsContent').innerHTML,/Second message|<option>Peer/);g.run('movePlanet(state.galaxy[0],"01:02:01");renderPolitics()');assert.equal(g.run('state.politics.banner'),'Second Galaxy');assert.equal(g.run('state.politics.ministers.economics'),undefined);assert.equal(g.run('state.politics.gc'),'');});
test('local election changes one ballot instead of accumulating repeat votes',()=>{const g=game();g.run('update=()=>save();ensureGalaxyPolitics();state.politics.votes={};state.politics.ballots={}');g.document.getElementById('gcVote').value='A. Commander';g.run('politicsAction("vote");politicsAction("vote")');assert.equal(g.run('state.politics.votes["A. Commander"]'),1);g.document.getElementById('gcVote').value='Nira Sol';g.run('politicsAction("vote")');assert.equal(g.run('state.politics.votes["A. Commander"]'),0);assert.equal(g.run('state.politics.votes["Nira Sol"]'),1);});
